local ui=require("ui");local hw=require("hw");local M={};local function q(d,n) if not d or type(d[n])~="function" then return "N/A" end;local ok,v=pcall(d[n]);return ok and tostring(v) or "N/A" end
function M.run(m) while true do ui.clear(m);ui.header(m,"ENVIRONMENT");local d=hw.environment();local w,h=m.getSize();if not d then m.setCursorPos(2,3);m.write("Environment Detector not detected.") else local a={"Biome: "..q(d,"getBiome"),"Dimension: "..q(d,"getDimension"),"Block light: "..q(d,"getBlockLightLevel"),"Sky light: "..q(d,"getSkyLightLevel"),"Raining: "..q(d,"isRaining"),"Thunder: "..q(d,"isThunder"),"Sunny: "..q(d,"isSunny")};for i,s in ipairs(a) do if i+2<h then m.setCursorPos(2,i+2);m.write(s:sub(1,w-2)) end end end;ui.back(m);local _,x,y=os.pullEvent("monitor_touch");if y==h and x<=10 then return end end end
return M
